class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int left = 1;
        int right = 0;
        for (int pile : piles) {
            right = Math.max(right, pile);
        }

        while (left < right) {
            int speed = left + (right - left) / 2;
            if (canFinish(piles, h, speed)) {
                right = speed;
            } else {
                left = speed + 1;
            }
        }

        return left;
    }

    private boolean canFinish(int[] piles, int h, int speed) {
        long hours = 0;
        for (int pile : piles) {
            hours += (pile + speed - 1L) / speed;
        }
        return hours <= h;
    }
}

class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int left = 1;
        int right = 0;
        for (int pile : piles) {
            right = Math.max(right, pile);
        }

        int answer = right;
        while (left <= right) {
            int speed = left + (right - left) / 2;
            if (canFinish(piles, h, speed)) {
                answer = speed;
                right = speed - 1;
            } else {
                left = speed + 1;
            }
        }

        return answer;
    }

    private boolean canFinish(int[] piles, int h, int speed) {
        long hours = 0;
        for (int pile : piles) {
            hours += (pile + speed - 1L) / speed;
            if (hours > h) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        long total = 0;
        int right = 0;
        for (int pile : piles) {
            total += pile;
            right = Math.max(right, pile);
        }

        int left = (int) Math.max(1, (total + h - 1L) / h);
        while (left < right) {
            int speed = left + (right - left) / 2;
            if (canFinish(piles, h, speed)) {
                right = speed;
            } else {
                left = speed + 1;
            }
        }
        return left;
    }

    private boolean canFinish(int[] piles, int h, int speed) {
        long hours = 0;
        for (int pile : piles) {
            hours += (pile + speed - 1L) / speed;
            if (hours > h) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int right = 0;
        for (int pile : piles) {
            right = Math.max(right, pile);
        }
        return search(piles, h, 1, right);
    }

    private int search(int[] piles, int h, int left, int right) {
        if (left >= right) {
            return left;
        }

        int speed = left + (right - left) / 2;
        if (canFinish(piles, h, speed)) {
            return search(piles, h, left, speed);
        }
        return search(piles, h, speed + 1, right);
    }

    private boolean canFinish(int[] piles, int h, int speed) {
        long hours = 0;
        for (int pile : piles) {
            hours += (pile + speed - 1L) / speed;
            if (hours > h) {
                return false;
            }
        }
        return true;
    }
}
